    TwistSquash::SquashKeyA(ALTAIR_KEY_B_D_IceLaneA, ALTAIR_KEY_B_D_IceLaneB, ALTAIR_KEY_B_D_IceLaneC, ALTAIR_KEY_B_D_IceLaneD, &(pWorkSpace->mKeyBoxB[3U][0]));

