    TwistSquash::SquashKeyA(ALTAIR_KEY_B_E_IceLaneA, ALTAIR_KEY_B_E_IceLaneB, ALTAIR_KEY_B_E_IceLaneC, ALTAIR_KEY_B_E_IceLaneD, &(pWorkSpace->mKeyBoxB[4U][0]));

