        const std::size_t aSourceIndexA = 1U * S_HALF + 3U * W_KEY + ((aIndex + 602U) & W_KEY1);
        const std::size_t aSourceIndexB = 0U * S_HALF + 6U * W_KEY + ((aIndex + 557U) & W_KEY1);
