        const std::size_t aSourceIndexB = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 93U) & W_KEY1);
        const std::size_t aSourceIndexC = 1U * (S_HALF >> 1U) + 0U * W_KEY + ((aIndex + 48U) & W_KEY1);
        const std::size_t aSourceIndexD = 1U * (S_HALF >> 1U) + 2U * W_KEY + ((aIndex + 3U) & W_KEY1);
        const std::size_t aDestinationIndex = 1U * W_KEY + aIndex;

